const url = process.env.URL;
globalThis.inputUrl = url;
const resp = await fetch(url, { redirect: 'follow' });
if (!resp.ok) throw new Error('Fetch failed with status ' + resp.status);
globalThis.raw = await resp.text();

const html = globalThis.raw;
const headingRegex = /<h[1-6][^>]*>(.*?)</h[1-6]>/gi;
let idx = 0;
const sections = [];
while (headingRegex.exec(html)) { sections.push(idx); idx++; }
if (sections.length === 0) throw new Error('No sections found');
globalThis.sectionsStr = sections.join(',');
